const UUID_V4_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/**
 * Returns the UUID v4 reference generated by the legacy draft POST redirect.
 * This value is presentation-only; it is not an authorization or ownership check.
 */
export function getCreatedOfferId(search: string): string | null {
  const created = new URLSearchParams(search).get("created");
  return created && UUID_V4_PATTERN.test(created) ? created : null;
}
